CREATE FUNCTION governance.protect_issued_approval() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.status IN ('APPROVED','REVOKED','REJECTED') THEN
  IF (to_jsonb(NEW)-ARRAY['status','revoked_at','updated_at','updated_by','version']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','revoked_at','updated_at','updated_by','version']) THEN RAISE EXCEPTION 'ISSUED_APPROVAL_IMMUTABLE'; END IF;
  IF NEW.status<>OLD.status AND NOT (OLD.status='APPROVED' AND NEW.status='REVOKED') THEN RAISE EXCEPTION 'NEW_APPROVAL_REQUIRED'; END IF;
  IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN RAISE EXCEPTION 'NEW_APPROVAL_REQUIRED'; END IF;
 END IF;
 RETURN NEW; END $$
